shader_type canvas_item;

// How much the dashboard changes at night
uniform float night_amount : hint_range(0.0, 1.0) = 0.0;

// Warm amber dashboard light
uniform vec4 night_color : source_color = vec4(1.0, 0.55, 0.20, 1.0);

// How bright the gauges stay at night
uniform float night_brightness : hint_range(0.1, 1.0) = 0.55;

void fragment() {
	// Blend between normal and night lighting
	COLOR.rgb = mix(COLOR.rgb, COLOR.rgb * night_color.rgb * night_brightness, night_amount);
}

func _process(delta: float) -> void:
	if not is_instance_valid(vehicle):
		return
	var target := 1.0 if vehicle.headlights_on else 0.0
	if night_amount == target:
		return
	var seconds := fade_in_seconds if target > night_amount else fade_out_seconds
	night_amount = move_toward(night_amount, target, delta / seconds)
	if absf(target - night_amount) < 0.000001:
		night_amount = target
	material.set_shader_parameter("night_amount", night_amount)

shader_type spatial;
render_mode blend_mix, depth_draw_never, cull_disabled;

// Fog settings
group_uniforms Fog;

uniform float fog_amount : hint_range(0.0, 1.0) = 0.25;
uniform float fog_opacity : hint_range(0.0, 1.0) = 0.45;
uniform vec4 fog_tint : source_color = vec4(0.82, 0.87, 0.90, 1.0);

uniform sampler2D fog_color : source_color, filter_linear, repeat_enable;
uniform sampler2D fog_normal : hint_normal, filter_linear, repeat_enable;
uniform sampler2D fog_data : filter_linear, repeat_enable;

void fragment() {
	// Read the three textures
	vec2 fog_uv = UV * texture_scale;
	vec3 color_sample = texture(fog_color, fog_uv).rgb;
	vec3 normal_sample = texture(fog_normal, fog_uv).rgb;
	float fog_thickness = texture(fog_data, fog_uv).r;

shader_type spatial;
render_mode unshaded;

// Same image, read in two different ways
uniform sampler2D color_read : source_color, filter_nearest;
uniform sampler2D data_read : filter_nearest;

// Switch between the two results
uniform bool show_data = false;

void fragment() {
	vec3 as_color = texture(color_read, UV).rgb;
	vec3 as_data = texture(data_read, UV).rgb;

	ALBEDO = show_data ? as_data : as_color;
}

func _check_contract() -> void:
	var shader := load(SHADER_PATH) as Shader
	var listed := {}
	for item in shader.get_shader_uniform_list():
		listed[item.name] = item.type
	_check(not listed.is_empty(), "Shader parses: get_shader_uniform_list() is not empty")
